"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useParams } from "next/navigation";
import { getBook } from "@/lib/api";
import { Book } from "@/types/book";

export default function BookDetailsPage() {
  const params = useParams();
  const id = params.id as string;

  const [book, setBook] = useState<Book | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchBook = async () => {
      try {
        setLoading(true);

        const data = await getBook(id);

        setBook(data);
      } catch (error) {
        console.error(error);
        setError("Failed to load book");
      } finally {
        setLoading(false);
      }
    };

    if (id) {
      fetchBook();
    }
  }, [id]);

  if (loading) {
    return (
      <main className="mx-auto max-w-4xl px-6 py-10">
        <p className="text-gray-600">Loading book...</p>
      </main>
    );
  }

  if (error || !book) {
    return (
      <main className="mx-auto max-w-4xl px-6 py-10">
        <div className="rounded-xl border bg-white p-8 text-center">
          <h1 className="text-2xl font-bold">
            Book not found
          </h1>

          <p className="mt-2 text-gray-600">
            {error || "This book does not exist."}
          </p>

          <Link
            href="/books"
            className="mt-6 inline-block rounded-lg bg-black px-5 py-3 text-white"
          >
            Back to Books
          </Link>
        </div>
      </main>
    );
  }

  return (
    <main className="mx-auto max-w-4xl px-6 py-10">
      <Link
        href="/books"
        className="mb-6 inline-block text-gray-600 hover:text-black"
      >
        ← Back to Books
      </Link>

      <div className="rounded-2xl border bg-white p-8 shadow-sm">
        <div className="mb-6">
          <span className="rounded-full bg-blue-100 px-3 py-1 text-sm text-blue-700">
            {book.category}
          </span>
        </div>

        <h1 className="text-4xl font-bold text-gray-900">
          {book.title}
        </h1>

        <p className="mt-3 text-xl text-gray-600">
          by {book.author}
        </p>

        <div className="mt-8 border-t pt-6">
          <p className="text-sm text-gray-500">
            Published Year
          </p>

          <p className="mt-1 text-lg font-semibold">
            {book.publishedYear}
          </p>
        </div>

        {book.description && (
          <div className="mt-6">
            <p className="text-sm text-gray-500">
              Description
            </p>

            <p className="mt-2 leading-7 text-gray-700">
              {book.description}
            </p>
          </div>
        )}

        <div className="mt-8 flex gap-3">
          <Link
            href={`/books/${book._id}/edit`}
            className="rounded-lg bg-black px-5 py-3 text-white hover:bg-gray-800"
          >
            Edit Book
          </Link>

          <Link
            href="/books"
            className="rounded-lg border px-5 py-3 text-gray-700 hover:bg-gray-100"
          >
            All Books
          </Link>
        </div>
      </div>
    </main>
  );
}